#!/usr/bin/env python3\n\"\"\"\nTest script to verify enhanced alignment scoring improvements.\n\"\"\"\n\nimport sys\nfrom pathlib import Path\n\n# Add parent directory to path\nsys.path.insert(0, str(Path(__file__).parent.parent.parent))\n\nfrom evaluation.data_models import (\n    ExperimentalSetup, GroundTruth, PaperContext,\n    ConfidenceLevel, calculate_component_alignment\n)\nfrom evaluation.unified_evaluator import UnifiedEvaluator\nfrom experimental_setup_eval.core.schema import EvaluationConfig\n\n\ndef test_semantic_matching():\n    \"\"\"Test that semantic matching works for similar but not identical names.\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"TEST 1: Semantic Matching\")\n    print(\"=\"*60)\n    \n    generated = [\"BERT\", \"GPT-2\", \"RoBERTa\"]\n    ground_truth = [\"BERT-base\", \"GPT2\", \"RoBERTa-large\"]\n    \n    result = calculate_component_alignment(generated, ground_truth, semantic_threshold=0.6)\n    \n    print(f\"\\nGenerated: {generated}\")\n    print(f\"Ground Truth: {ground_truth}\")\n    print(f\"\\nRecall: {result.recall:.2f}\")\n    print(f\"Precision: {result.precision:.2f}\")\n    print(f\"F1 Score: {result.f1_score:.2f}\")\n    print(f\"\\nMatches ({len(result.matches)}):\")\n    for match in result.matches:\n        print(f\"  - {match.generated} -> {match.ground_truth} ({match.method}, score: {match.score:.2f})\")\n    \n    print(f\"\\nMissing: {result.missing}\")\n    print(f\"Extra: {result.extra}\")\n    \n    assert result.recall >= 0.5, \"Should match at least some items semantically\"\n    assert len(result.matches) > 0, \"Should have some matches\"\n    print(\"\\n✓ Semantic matching test PASSED\")\n\n\ndef test_f1_vs_recall():\n    \"\"\"Test that F1-based scoring behaves differently from recall-only.\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"TEST 2: F1 vs Recall Scoring\")\n    print(\"=\"*60)\n    \n    # Setup with high recall but low precision\n    generated_many = [\"BERT\", \"GPT-2\", \"ResNet\", \"VGG\", \"AlexNet\", \"Random Baseline\"]\n    ground_truth_few = [\"BERT\", \"GPT-2\"]\n    \n    result = calculate_component_alignment(generated_many, ground_truth_few)\n    \n    print(f\"\\nGenerated (many): {generated_many}\")\n    print(f\"Ground Truth (few): {ground_truth_few}\")\n    print(f\"\\nRecall: {result.recall:.2f} (% of ground truth found)\")\n    print(f\"Precision: {result.precision:.2f} (% of generated that match)\")\n    print(f\"F1 Score: {result.f1_score:.2f} (balanced metric)\")\n    \n    # F1 should be lower than recall due to low precision\n    print(f\"\\nF1 < Recall? {result.f1_score < result.recall} (should be True)\")\n    assert result.f1_score < result.recall, \"F1 should penalize low precision\"\n    print(\"\\n✓ F1 vs Recall test PASSED\")\n\n\ndef test_partial_ground_truth():\n    \"\"\"Test that partial ground truth handling works correctly.\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"TEST 3: Partial Ground Truth Handling\")\n    print(\"=\"*60)\n    \n    config = EvaluationConfig()\n    evaluator = UnifiedEvaluator(config)\n    \n    setup = ExperimentalSetup(\n        baselines=[\"Random\", \"BERT\", \"GPT-2\"],\n        metrics=[\"Accuracy\", \"F1\"],\n        datasets=[\"GLUE\", \"SQuAD\"]\n    )\n    \n    # Ground truth with only baselines and metrics (datasets redacted)\n    ground_truth_partial = GroundTruth(\n        baselines=[\"Random\", \"BERT\"],\n        metrics=[\"Accuracy\"],\n        datasets=[],  # Missing/redacted\n        has_experiments=True,\n        extraction_confidence=ConfidenceLevel.MEDIUM\n    )\n    \n    result = evaluator.score_alignment(setup, ground_truth_partial)\n    \n    print(f\"\\nSetup Baselines: {setup.baselines}\")\n    print(f\"GT Baselines: {ground_truth_partial.baselines}\")\n    print(f\"Setup Metrics: {setup.metrics}\")\n    print(f\"GT Metrics: {ground_truth_partial.metrics}\")\n    print(f\"Setup Datasets: {setup.datasets}\")\n    print(f\"GT Datasets: {ground_truth_partial.datasets} (REDACTED)\")\n    \n    print(f\"\\nOverall Alignment: {result.overall_alignment:.2f}\")\n    print(f\"Confidence: {result.confidence}\")\n    print(f\"\\nComponent Scores:\")\n    for key, value in result.component_scores.items():\n        if 'f1' in key or 'alignment' in key:\n            print(f\"  {key}: {value:.2f}\")\n    \n    # Should have valid score even with missing datasets\n    assert result.overall_alignment > 0, \"Should compute alignment even with partial ground truth\"\n    assert 'dataset_f1' not in result.component_scores or result.component_scores.get('dataset_f1') == 0, \"Dataset alignment should be 0 or not present\"\n    print(\"\\n✓ Partial ground truth test PASSED\")\n\n\ndef test_qualitative_alignment():\n    \"\"\"Test that qualitative alignment (hypotheses, controls, protocol) is computed.\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"TEST 4: Qualitative Alignment\")\n    print(\"=\"*60)\n    \n    config = EvaluationConfig()\n    evaluator = UnifiedEvaluator(config)\n    \n    setup = ExperimentalSetup(\n        baselines=[\"BERT\"],\n        metrics=[\"Accuracy\"],\n        datasets=[\"GLUE\"],\n        hypotheses=[\"BERT will outperform baseline\"],\n        control_groups=[\"Random baseline\"],\n        experimental_protocol={\"cross_validation\": \"5-fold\", \"runs\": 3}\n    )\n    \n    ground_truth = GroundTruth(\n        baselines=[\"BERT\"],\n        metrics=[\"Accuracy\"],\n        datasets=[\"GLUE\"],\n        has_experiments=True,\n        extraction_confidence=ConfidenceLevel.HIGH,\n        experimental_details={\n            \"hypotheses\": [\"BERT outperforms baselines\"],\n            \"controls\": [\"Random\"],\n            \"experimental_protocol\": {\"cross_validation\": True, \"runs\": 5}\n        }\n    )\n    \n    result = evaluator.score_alignment(setup, ground_truth)\n    \n    print(f\"\\nOverall Alignment: {result.overall_alignment:.2f}\")\n    print(f\"Confidence: {result.confidence}\")\n    print(f\"\\nQualitative Alignments:\")\n    print(f\"  Hypotheses: {result.hypotheses_alignment:.2f}\")\n    print(f\"  Controls: {result.control_alignment:.2f}\")\n    print(f\"  Protocol: {result.protocol_alignment:.2f}\")\n    \n    # Should have non-zero qualitative alignments\n    assert result.hypotheses_alignment > 0, \"Should compute hypotheses alignment\"\n    assert result.control_alignment >= 0, \"Should compute control alignment\"\n    assert result.protocol_alignment > 0, \"Should compute protocol alignment\"\n    print(\"\\n✓ Qualitative alignment test PASSED\")\n\n\nif __name__ == \"__main__\":\n    print(\"\\n\" + \"#\"*60)\n    print(\"# Testing Enhanced Alignment Scoring Implementation\")\n    print(\"#\"*60)\n    \n    try:\n        test_semantic_matching()\n        test_f1_vs_recall()\n        test_partial_ground_truth()\n        test_qualitative_alignment()\n        \n        print(\"\\n\" + \"#\"*60)\n        print(\"# ALL TESTS PASSED ✓\")\n        print(\"#\"*60 + \"\\n\")\n    except Exception as e:\n        print(f\"\\n\\n❌ TEST FAILED: {e}\")\n        import traceback\n        traceback.print_exc()\n        sys.exit(1)\n
